/* Photo-led launch page. Existing detailed overview stays available below. */
(function(root){
'use strict';
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function mount(host,kind){const logistics=kind==='logistics';const photo=root.IndustrialPhotos?.photos.find(p=>p.id===(logistics?'materials-steel-truck':'mechanical-04'));const links=logistics?[['01','仓储作业','入库、库存与拣选','warehouse'],['02','运输配送','查看运输任务与签收','transport'],['03','视觉工作台','实拍图像与预设标注','multimodal']]:[['01','课程与实验','从课程任务进入实践','learning'],['02','视觉工作台','实拍图像与预设标注','multimodal'],['03','数字孪生','查看场景与组件流程','twin']];host.innerHTML=`<section class="studio-launch"><div class="studio-welcome"><span>${logistics?'MODERN LOGISTICS':'CONNECTED INDUSTRY'} / LEARNING STUDIO</span><span>教学工作空间</span></div><div class="studio-hero"><div class="studio-hero-copy"><div class="studio-kicker">${logistics?'现代物流实训':'物联网技术实训'}</div><h1>${logistics?'让每一步流转，<br>都成为实践。':'从真实现场，<br>走进技术实践。'}</h1><p>${logistics?'在同一工作台串联仓储、运输与现场数据。':'围绕设备、图像与数据，把知识变成可操作的任务。'}</p><div class="studio-hero-actions"><button class="studio-primary" data-studio-page="${logistics?'warehouse':'multimodal'}">${logistics?'进入仓储工作台':'进入视觉工作台'} <span>↗</span></button><button class="studio-secondary" data-studio-page="${logistics?'multimodal':'learning'}">${logistics?'查看实拍样例':'浏览课程'} →</button></div><div class="studio-hero-foot"><span class="studio-dot"></span> 已预填教学样例，直接开始操作</div></div><figure class="studio-hero-photo">${photo?`<img src="/static/industrial-photos/${e(photo.file)}" alt="${e(photo.description)}"><figcaption><span>${logistics?'MATERIALS IN MOTION':'MECHANICAL DETAILS'}</span><a href="${e(photo.source)}" target="_blank" rel="noopener">${e(photo.author)} · ${e(photo.license)} ↗</a></figcaption>`:''}<div class="studio-photo-number">${logistics?'02':'01'}<small>FIELD STUDY</small></div></figure></div><div class="studio-section-label"><h2>选择一个工作台</h2><span>按任务进入，无需从头配置</span></div><div class="studio-launch-grid">${links.map(([n,title,sub,page])=>`<button class="studio-launch-item" data-studio-page="${page}"><span class="studio-item-number">${n}</span><span><strong>${title}</strong><small>${sub}</small></span><span class="studio-item-arrow">↗</span></button>`).join('')}</div><div class="studio-bottom-line"><span>课程、任务与记录保存在当前工作区</span><button data-studio-page="exams">题库与考核 →</button><button data-studio-page="admin">教学管理 →</button></div></section>`;host.onclick=event=>{const b=event.target.closest('[data-studio-page]');if(b)root.navigate(b.dataset.studioPage);};}
root.PresetDashboard={mount};
})(window);
